package bottlesong

import (
	"fmt"
	"strings"
)

// Recite returns the lyrics of the bottle song, starting with startBottles
// bottles and reciting takeDown verses.
func Recite(startBottles, takeDown int) []string {
	var lines []string
	for i := 0; i < takeDown; i++ {
		bottles := startBottles - i
		if i > 0 {
			lines = append(lines, "")
		}
		lines = append(lines,
			fmt.Sprintf("%s green bottles hanging on the wall,", Title(bottlesString(bottles))),
			fmt.Sprintf("%s green bottles hanging on the wall,", Title(bottlesString(bottles))),
			"And if one green bottle should accidentally fall,",
			fmt.Sprintf("There'll be %s green bottle%s hanging on the wall.",
				bottlesString(bottles-1), plural(bottles-1)),
		)
	}
	return lines
}

// bottlesString returns the number of bottles spelled out, with "no" for zero.
func bottlesString(n int) string {
	switch n {
	case 0:
		return "no"
	case 1:
		return "one"
	case 2:
		return "two"
	case 3:
		return "three"
	case 4:
		return "four"
	case 5:
		return "five"
	case 6:
		return "six"
	case 7:
		return "seven"
	case 8:
		return "eight"
	case 9:
		return "nine"
	case 10:
		return "ten"
	default:
		return fmt.Sprintf("%d", n)
	}
}

// plural returns "s" for plural counts and "" for singular counts.
func plural(n int) string {
	if n == 1 {
		return ""
	}
	return "s"
}

// Title is a copy of the deprecated strings.Title function, capitalizing
// the first letter of each word.
func Title(s string) string {
	prev := ' '
	return strings.Map(
		func(r rune) rune {
			if isSeparator(prev) {
				prev = r
				return unicodeToTitle(r)
			}
			prev = r
			return r
		},
		s)
}

// unicodeToTitle is a minimal replacement for unicode.ToTitle.
func unicodeToTitle(r rune) rune {
	if 'a' <= r && r <= 'z' {
		return r - 32
	}
	return r
}

// isSeparator reports whether r is a word separator.
func isSeparator(r rune) bool {
	if r <= 0x7F {
		switch {
		case '0' <= r && r <= '9':
			return false
		case 'a' <= r && r <= 'z':
			return false
		case 'A' <= r && r <= 'Z':
			return false
		case r == '_':
			return false
		}
		return true
	}
	return false
}

